(function(root){
 // The stage and actor share this single logical ground position. Alpha bounds exclude empty sprite margins.
 const enemyPad=Object.freeze({x:342/480,y:132/240});
 function inkBounds(data,w,h){let left=w,right=-1,bottom=-1;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(data[(y*w+x)*4+3]>24){left=Math.min(left,x);right=Math.max(right,x);bottom=Math.max(bottom,y);}if(right<0)return{centerX:.5,foot:1};let footLeft=w,footRight=-1;for(let y=Math.max(0,bottom-2);y<=bottom;y++)for(let x=0;x<w;x++)if(data[(y*w+x)*4+3]>24){footLeft=Math.min(footLeft,x);footRight=Math.max(footRight,x);}return{centerX:(footLeft+footRight+1)/2/w,foot:(bottom+1)/h};}
 function placement(stage,sprite,bounds){return{left:stage.width*enemyPad.x-sprite.width*bounds.centerX-(sprite.offsetLeft||0),top:stage.height*enemyPad.y-sprite.height*bounds.foot-(sprite.offsetTop||0)};}
 function fitDrawing(w,h,cw,ch){const scale=Math.min(w/cw,h/ch);return{width:cw*scale,height:ch*scale};}
 function attach(stage,actor,canvas){const align=()=>{if(!stage.clientWidth||!canvas.clientWidth)return;if(actor.dataset?.boss==='true')actor.style.setProperty('--boss-limit',Math.floor(stage.clientHeight*.53)+'px');let bounds={centerX:.5,foot:1};try{bounds=inkBounds(canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height);}catch{/* Optional pixel inspection must never prevent combat. */}const point=placement({width:stage.clientWidth,height:stage.clientHeight},{width:canvas.clientWidth,height:canvas.clientHeight,offsetLeft:actor===canvas?0:canvas.offsetLeft,offsetTop:actor===canvas?0:canvas.offsetTop},bounds);actor.style.left=point.left+'px';actor.style.top=point.top+'px';actor.style.right='auto';};const observer=new ResizeObserver(align);observer.observe(stage);observer.observe(canvas);align();return{align,disconnect:()=>observer.disconnect()};}
 const api={enemyPad,inkBounds,placement,fitDrawing,attach};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.GameStageLayout=api;
})(typeof window!=='undefined'?window:globalThis);
